// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    // fuzzed params: caller (an address attempting the transfer) and newOwner (the address to become owner)
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid the zero-address for newOwner as an admissible domain tweak (still allowed if fuzz finds it)
        vm.assume(caller != address(0));

        // Initial owner is c.owner() right after deployment
        address initialOwner = c.owner();

        bool success;

        // Make caller attempt to call transferOwnership
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // The universal property: only the current owner can change ownership.
        // Thus, if the caller is not the initial owner, the call must NOT succeed (i.e., revert or have no effect).
        // If the caller IS the initial owner, the call must succeed and owner becomes newOwner.
        // We assert this property by checking the post-call owner equals expected outcome derived from caller equality.

        if (caller == initialOwner) {
            // If the rightful owner called, the call must succeed and owner must now be newOwner
            // We assert that the call succeeded and the owner getter reflects newOwner.
            assertTrue(success && c.owner() == newOwner);
        } else {
            // If a non-owner called, the call must NOT succeed (access control), and owner must remain the initial owner
            assertTrue(!success && c.owner() == initialOwner);
        }
    }
}
